import os
import hmac
import hashlib
import json
import struct
import tempfile
from pathlib import Path
from typing import Optional, Tuple
import secrets

# Secure document storage service with integrity verification

SECRET_KEY = os.environ.get('HMAC_SECRET', secrets.token_hex(32)).encode()
STORAGE_ROOT = Path(tempfile.mkdtemp(prefix='docstor_'))
MAX_PATH_DEPTH = 8
MAX_COMPONENT_LEN = 64

def compute_mac(data: bytes) -> bytes:
    """Compute HMAC-SHA256 for integrity verification."""
    return hmac.new(SECRET_KEY, data, hashlib.sha256).digest()

def verify_mac(data: bytes, mac: bytes) -> bool:
    """Constant-time MAC verification."""
    expected = hmac.new(SECRET_KEY, data, hashlib.sha256).digest()
    return hmac.compare_digest(expected, mac)

class DocumentEnvelope:
    """Binary envelope format:
    [2 bytes: version][4 bytes: path_len][path_len bytes: path]
    [4 bytes: body_len][body_len bytes: body][32 bytes: hmac]
    """
    VERSION = 2

    @staticmethod
    def pack(doc_path: str, body: bytes) -> bytes:
        path_bytes = doc_path.encode('utf-8')
        header = struct.pack('>HI', DocumentEnvelope.VERSION, len(path_bytes))
        body_header = struct.pack('>I', len(body))
        payload = header + path_bytes + body_header + body
        mac = compute_mac(payload)
        return payload + mac

    @staticmethod
    def unpack(envelope: bytes) -> Tuple[str, bytes]:
        if len(envelope) < 2 + 4 + 4 + 32:
            raise ValueError("Envelope too short")

        version, path_len = struct.unpack('>HI', envelope[0:6])
        if version != DocumentEnvelope.VERSION:
            raise ValueError(f"Unsupported version: {version}")

        # Validate path_len is reasonable
        if path_len > 2048:
            raise ValueError("Path too long")

        path_end = 6 + path_len
        if path_end + 4 + 32 > len(envelope):
            raise ValueError("Invalid envelope structure")

        doc_path = envelope[6:path_end].decode('utf-8')

        body_len = struct.unpack('>I', envelope[path_end:path_end+4])[0]
        body_start = path_end + 4
        body_end = body_start + body_len

        # Verify total length matches
        expected_total = body_end + 32
        if expected_total != len(envelope):
            raise ValueError("Length mismatch")

        # Verify MAC over payload (everything except last 32 bytes)
        payload = envelope[:body_end]
        mac = envelope[body_end:body_end+32]
        if not verify_mac(payload, mac):
            raise ValueError("MAC verification failed")

        body = envelope[body_start:body_end]
        return doc_path, body


def sanitize_path_component(component: str) -> str:
    """Remove dangerous characters from a single path component."""
    # Allow alphanumeric, dash, underscore, dot (but not leading dot)
    cleaned = ''.join(c for c in component if c.isalnum() or c in '-_.')
    if cleaned.startswith('.'):
        cleaned = cleaned.lstrip('.')
    return cleaned[:MAX_COMPONENT_LEN]


def validate_document_path(doc_path: str) -> Path:
    """Validate and resolve document path safely.

    Security: prevents path traversal by validating each component
    and checking the resolved path is within STORAGE_ROOT.
    """
    if not doc_path:
        raise ValueError("Empty path")

    # Normalize separators
    normalized = doc_path.replace('\\', '/')

    # Split into components
    components = [c for c in normalized.split('/') if c]

    if len(components) > MAX_PATH_DEPTH:
        raise ValueError(f"Path too deep: {len(components)} > {MAX_PATH_DEPTH}")

    # Check for traversal attempts
    for comp in components:
        if comp == '..' or comp == '.':
            raise ValueError("Path traversal detected")

    # Sanitize each component
    sanitized = [sanitize_path_component(c) for c in components]

    # Filter empty components after sanitization
    sanitized = [c for c in sanitized if c]

    if not sanitized:
        raise ValueError("Path resolved to empty")

    # Build the target path
    target = STORAGE_ROOT
    for comp in sanitized:
        target = target / comp

    # Final resolution check - resolve symlinks and verify containment
    # NOTE: We resolve the parent since the file may not exist yet
    target_parent = target.parent
    target_parent.mkdir(parents=True, exist_ok=True)
    resolved_parent = target_parent.resolve()

    if not str(resolved_parent).startswith(str(STORAGE_ROOT.resolve())):
        raise ValueError("Path escapes storage root")

    return target


def decode_metadata(raw: bytes) -> dict:
    """Decode document metadata from binary format.

    Format: JSON with optional binary attachments.
    Uses safe JSON parsing - no pickle/marshal.
    """
    # Check for our metadata magic bytes
    if len(raw) >= 4 and raw[0:2] == b'\x89\x50':  # PNG-like magic for binary
        # Binary metadata format: skip 4-byte header, rest is JSON
        try:
            return json.loads(raw[4:])
        except (json.JSONDecodeError, UnicodeDecodeError):
            return {"raw": raw[4:].hex(), "format": "binary"}

    # Try JSON directly
    try:
        result = json.loads(raw)
        if isinstance(result, dict):
            return result
        return {"value": result}
    except (json.JSONDecodeError, UnicodeDecodeError):
        return {"raw": raw.hex(), "format": "unknown"}


def store_document(doc_path: str, content: bytes, metadata: Optional[bytes] = None) -> dict:
    """Store a document with integrity protection."""
    target = validate_document_path(doc_path)

    # Create envelope with MAC
    envelope = DocumentEnvelope.pack(doc_path, content)

    # Write atomically
    tmp_path = target.with_suffix('.tmp')
    try:
        tmp_path.write_bytes(envelope)
        tmp_path.rename(target)
    except Exception:
        tmp_path.unlink(missing_ok=True)
        raise

    result = {"status": "stored", "path": doc_path, "size": len(content)}

    if metadata:
        result["metadata"] = decode_metadata(metadata)

    return result


def retrieve_document(doc_path: str) -> Tuple[bytes, dict]:
    """Retrieve and verify a document."""
    target = validate_document_path(doc_path)

    if not target.exists():
        raise FileNotFoundError(f"Document not found: {doc_path}")

    envelope = target.read_bytes()
    verified_path, body = DocumentEnvelope.unpack(envelope)

    return body, {"path": verified_path, "size": len(body)}


def handle_batch_import(manifest_data: bytes) -> list:
    """Process a batch import manifest.

    Manifest format: newline-separated JSON records.
    Each record: {"path": "...", "content_b64": "...", "meta": {...}}
    """
    import base64
    results = []

    for line_num, line in enumerate(manifest_data.decode('utf-8').splitlines(), 1):
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        try:
            record = json.loads(line)
            if not isinstance(record, dict):
                raise ValueError("Record must be object")

            path = record.get('path', '')
            content_b64 = record.get('content_b64', '')
            content = base64.b64decode(content_b64)
            meta = json.dumps(record.get('meta', {})).encode()

            result = store_document(path, content, meta)
            results.append({"line": line_num, **result})
        except Exception as e:
            results.append({"line": line_num, "status": "error", "error": str(e)})

    return results


def search_documents(prefix: str, max_results: int = 100) -> list:
    """Search for documents by path prefix."""
    # Validate prefix using same rules
    if prefix:
        validate_document_path(prefix)

    results = []
    search_root = STORAGE_ROOT

    # Cap max_results
    max_results = min(max_results, 1000)

    for path in search_root.rglob('*'):
        if path.is_file() and not path.suffix == '.tmp':
            rel = path.relative_to(search_root)
            rel_str = str(rel)
            if not prefix or rel_str.startswith(prefix):
                results.append(rel_str)
                if len(results) >= max_results:
                    break

    return results


# === HTTP Request Handler ===

def handle_request(method: str, path: str, body: bytes = b'', headers: dict = None) -> Tuple[int, dict, bytes]:
    """Simple HTTP-like request handler."""
    headers = headers or {}

    try:
        if method == 'PUT' and path.startswith('/docs/'):
            doc_path = path[6:]  # Strip '/docs/'
            meta = headers.get('X-Metadata', '').encode() or None
            result = store_document(doc_path, body, meta)
            return 200, {"Content-Type": "application/json"}, json.dumps(result).encode()

        elif method == 'GET' and path.startswith('/docs/'):
            doc_path = path[6:]
            content, info = retrieve_document(doc_path)
            return 200, {"Content-Type": "application/octet-stream", "X-Info": json.dumps(info)}, content

        elif method == 'POST' and path == '/batch-import':
            results = handle_batch_import(body)
            return 200, {"Content-Type": "application/json"}, json.dumps(results).encode()

        elif method == 'GET' and path.startswith('/search'):
            # Parse query params (simplified)
            prefix = headers.get('X-Prefix', '')
            results = search_documents(prefix)
            return 200, {"Content-Type": "application/json"}, json.dumps(results).encode()

        else:
            return 404, {}, b'Not Found'

    except ValueError as e:
        return 400, {"Content-Type": "application/json"}, json.dumps({"error": str(e)}).encode()
    except FileNotFoundError as e:
        return 404, {"Content-Type": "application/json"}, json.dumps({"error": str(e)}).encode()
    except Exception as e:
        return 500, {"Content-Type": "application/json"}, json.dumps({"error": "Internal error"}).encode()
